//! Strongly-typed identifier aliases for all domain entities.
//!
//! Every identifier is a [`uuid::Uuid`] (or `i64` for auto-increment surrogate
//! keys) wrapped in a type alias so that the compiler catches accidental
//! mix-ups (e.g. passing a `DocId` where a `WorkspaceId` is expected).
//!
//! The exception is [`DocHistoryId`] and [`DocUpdateId`], which are sequential
//! `i64` values generated by the database to preserve insertion order.

use uuid::Uuid;

// ─── User / Auth ──────────────────────────────────────────────────────────────

/// Unique identifier for a registered user account.
pub type UserId = Uuid;
/// Unique identifier for an authenticated browser/device session.
pub type SessionId = Uuid;
/// Unique identifier for an email-verification token record.
pub type VerificationTokenId = Uuid;
/// Unique identifier for an issued access token (JWT jti / opaque token).
pub type AccessTokenId = Uuid;
/// Unique identifier for an OAuth connected-account record.
pub type ConnectedAccountId = Uuid;
/// Unique identifier for a magic-link one-time password record.
pub type MagicLinkOtpId = Uuid;

// ─── Workspace ────────────────────────────────────────────────────────────────

/// Unique identifier for a collaborative workspace.
pub type WorkspaceId = Uuid;
/// Unique identifier for a workspace invite link.
pub type InviteLinkId = Uuid;

// ─── Databases ─────────────────────────────────────────────────────

/// Unique identifier for a server-backed workspace database.
pub type DatabaseId = Uuid;
/// Unique identifier for a field definition inside a workspace database.
pub type DatabaseFieldId = Uuid;
/// Unique identifier for one database row/document link.
pub type DatabaseRowId = Uuid;
/// Unique identifier for a saved database view.
pub type DatabaseViewId = Uuid;
/// Unique identifier for a saved CSV mapping template (P-DB-27).
pub type DatabaseCsvMappingTemplateId = Uuid;
/// Unique identifier for a background `database.bulkImport` /
/// `database.bulkExport` job (P-DB-26). One row per job.
pub type DatabaseImportJobId = Uuid;
/// Unique identifier for one staged full-workspace import.
pub type WorkspaceImportId = Uuid;
/// Unique identifier for one durable cross-workspace content operation.
pub type WorkspaceContentOperationId = Uuid;
/// Unique identifier for a workspace automation definition.
pub type WorkspaceAutomationId = Uuid;
/// Unique identifier for one automation run.
pub type WorkspaceAutomationRunId = Uuid;
/// Unique identifier for one persisted automation action result.
pub type WorkspaceAutomationActionId = Uuid;

// ─── Document ─────────────────────────────────────────────────────────────────

/// Unique identifier for a collaborative document.
pub type DocId = Uuid;
/// Unique identifier for one stored document graph occurrence.
pub type DocumentGraphOccurrenceId = Uuid;
/// Sequential identifier for a historical document snapshot (history entry).
/// Uses `i64` to preserve ordering without UUID generation overhead.
pub type DocHistoryId = i64;
/// Sequential identifier for a raw Yjs update record appended to a document.
pub type DocUpdateId = i64;

// ─── Blob / Storage ───────────────────────────────────────────────────────────

/// Unique identifier for a stored binary blob (image, attachment, etc.).
pub type BlobId = Uuid;
/// Unique identifier for a multipart upload session.
pub type MultipartUploadId = Uuid;
/// Unique identifier for a comment attachment record.
pub type CommentAttachmentId = Uuid;

// ─── Social ───────────────────────────────────────────────────────────────────

/// Unique identifier for a document comment.
pub type CommentId = Uuid;
/// Unique identifier for a user notification.
pub type NotificationId = Uuid;

// ─── Calendar ─────────────────────────────────────────────────────────────────

/// Unique identifier for a connected calendar account (OAuth credential set).
pub type CalendarAccountId = Uuid;
/// Unique identifier for a calendar subscription within an account.
pub type CalendarSubscriptionId = Uuid;
/// Unique identifier for a calendar event.
pub type CalendarEventId = Uuid;
/// Unique identifier for a recurring event instance.
pub type CalendarEventInstanceId = Uuid;
/// Unique identifier for a calendar event participant record.
pub type CalendarEventParticipantId = Uuid;
/// Unique identifier for a calendar reminder.
pub type CalendarReminderId = Uuid;
/// Unique identifier for a user-defined calendar event tag.
pub type CalendarEventTagId = Uuid;

// ─── Copilot ──────────────────────────────────────────────────────────────────

/// Unique identifier for an AI copilot conversation session.
pub type CopilotSessionId = Uuid;
/// Unique identifier for a message within a copilot session.
pub type CopilotMessageId = Uuid;
/// Unique identifier for a reusable copilot context bundle.
pub type CopilotContextId = Uuid;
/// Unique identifier for a single item inside a copilot context bundle.
pub type CopilotContextItemId = Uuid;
/// Unique identifier for a background AI processing job.
pub type CopilotJobId = Uuid;

// ─── Organisation und Organisationseinheiten ─────────────────────────────────

/// Unique identifier for an `organization` row (mandant frame).
pub type OrganizationId = Uuid;
/// Unique identifier for an `organization_unit_type` row.
pub type OrganizationUnitTypeId = Uuid;
/// Unique identifier for an `organization_unit` row (OU).
pub type OrganizationUnitId = Uuid;
/// Unique identifier for an `organization_project_request` row.
pub type OrganizationProjectRequestId = Uuid;

// ─── MCP API Keys ─────────────────────────────────────────────────────────────

/// Unique identifier for an MCP API key record.
pub type ApiKeyId = Uuid;
